         {1: 'Kin', 2: 'lees', 3: ['die nuus', 'die nuus oor die aardbewing'], 4: 'Kin', 5: 'mis', 6: ['sy gesin en sy maats', 'sy gesin'], 7: 'Ons', 8: 'speel', 9: 'sokker', 10: 'Kin', 11: 'lees', 12: ['’n boek', 'boek'], 13: 'Hy', 14: 'speel', 15: 'rekenaarspeletjies'},
